SELECT * FROM (
    SELECT * FROM (
        SELECT BOT_NUM, USER_NUM, TEAM_NUM, MESSAGE, SENDER, REG_DATE
        FROM BOT_LOG
        WHERE USER_NUM = #{user_num}
          AND TEAM_NUM = #{team_num}
        ORDER BY REG_DATE DESC, BOT_NUM DESC
    )
    WHERE ROWNUM <= 50
)
ORDER BY REG_DATE ASC, BOT_NUM ASC
